mapper.select:
SELECT coalesce(sum(size), 0) FROM forge_storage_object
WHERE status <> 'DELETED'
AND id <> #{excludeId}

mapper.update:
UPDATE forge_storage_object SET status = 'EXPIRED', expired_at = #{now}
WHERE id = #{id} AND status IN ('PENDING', 'STORED')
AND (retention_expires_at <= #{now} OR (status = 'PENDING' AND upload_expires_at <= #{now}))

mapper.select:
SELECT id, object_key, purpose, filename, content_type, size, status, upload_expires_at, stored_at, retention_expires_at, expired_at
FROM forge_storage_object
WHERE purpose = #{purpose} AND status IN ('EXPIRED', 'PURGE_PENDING')
AND expired_at <= #{graceCutoff} AND upload_expires_at <= #{now}
AND id > #{after}
ORDER BY id FETCH FIRST #{limit} ROWS ONLY
